# ══════════════════════════════════════════════════════
# 工具函数
# ══════════════════════════════════════════════════════

def load_json(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except:
        return None

def short_name(p):
    return os.path.splitext(os.path.basename(p))[0] if p else ""

def norm_path(ref, base_dir):
    if not ref: return None
    ref = ref.replace("file://./", "").replace("file://", "")
    return os.path.normpath(os.path.join(base_dir, ref))

def cartesian(lists):
    """简易笛卡尔积: [[a,b],[c,d]] → [[a,c],[a,d],[b,c],[b,d]]"""
    if not lists: return [[]]
    result = []
    for item in lists[0]:
        if isinstance(item, tuple):
            item = item[0]
        for rest in cartesian(lists[1:]):
            result.append([item] + (rest if isinstance(rest, list) else [rest]))
    return result

def get_uuid(tag_ref):
    if not tag_ref: return ""
    return tag_ref.get("_RecordId", "") or tag_ref.get("_RecordId_", "")


